{
  "title": "The Lantern Road Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A worn map is spread across a tavern table at dawn.",
      "visual_description": "Low candlelight over a cracked oak table, a hand-drawn map of the ruined royal city weighed down with coins, steam rising from a clay mug.",
      "characters": ["Maren Vale", "Iskar Tov"]
    },
    {
      "scene_number": 2,
      "caption": "The team approaches the broken outer gates.",
      "visual_description": "Massive iron-banded gates split open, ivy crawling over fallen statues, gray morning fog pooling at the threshold.",
      "characters": ["Maren Vale", "Iskar Tov", "Brann Holt"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople warn them to turn back.",
      "visual_description": "A cluster of hooded refugees behind a barricade of carts, lanterns trembling in their hands, ash drifting from the sky.",
      "characters": ["Maren Vale", "Old Petra"]
    },
    {
      "scene_number": 4,
      "caption": "A torn royal banner flutters above the empty plaza.",
      "visual_description": "A great square littered with shattered cobbles, a crimson banner with a silver stag half-burned, hanging from a leaning flagpole.",
      "characters": ["Iskar Tov", "Brann Holt"]
    },
    {
      "scene_number": 5,
      "caption": "Brann scouts the rooftops for armored patrols.",
      "visual_description": "A lean scout crouched on a tiled rooftop, bow lowered, watching mailed soldiers march below through a narrow alley.",
      "characters": ["Brann Holt"]
    },
    {
      "scene_number": 6,
      "caption": "The cursed tower looms at the city's heart.",
      "visual_description": "A black spiral tower wreathed in green vapor, cracked windows glowing faintly, ravens circling the spire.",
      "characters": ["Maren Vale", "Iskar Tov", "Brann Holt"]
    },
    {
      "scene_number": 7,
      "caption": "Iskar deciphers wards carved into a magic door.",
      "visual_description": "A close shot of glowing runes pulsing on a stone arch, a robed figure tracing symbols with a glowing fingertip.",
      "characters": ["Iskar Tov"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a dragon stir the team's nerves.",
      "visual_description": "Enormous clawmarks gouged into a marble wall, a single charred scale lying on the floor, dust motes catching pale light.",
      "characters": ["Maren Vale", "Brann Holt"]
    },
    {
      "scene_number": 9,
      "caption": "Sleepy Chamberlain Odo is found locked in a pantry.",
      "visual_description": "A round man in dusty velvet robes blinking against torchlight, a half-eaten pear in his hand, mice scattering at his feet.",
      "characters": ["Chamberlain Odo", "Brann Holt"]
    },
    {
      "scene_number": 10,
      "caption": "Odo whispers the secret way to the inner keep.",
      "visual_description": "The chamberlain bent over the map, jabbing a finger at a hidden servant's passage, candlelight flickering across worried faces.",
      "characters": ["Maren Vale", "Iskar Tov", "Chamberlain Odo"]
    },
    {
      "scene_number": 11,
      "caption": "An armored patrol blocks the corridor.",
      "visual_description": "Three soldiers in scorched plate filling a narrow hall, halberds lowered, their visors reflecting torchlight.",
      "characters": ["Brann Holt", "Captain Reeve"]
    },
    {
      "scene_number": 12,
      "caption": "Iskar opens a hidden magic door with a glyph.",
      "visual_description": "A stone wall splitting along glowing seams, blue light spilling into the corridor, a mage's hand pressed to the central rune.",
      "characters": ["Iskar Tov", "Maren Vale"]
    },
    {
      "scene_number": 13,
      "caption": "They find Princess Aenor chained in the tower cell.",
      "visual_description": "A young woman in a tattered gown chained to a cold iron ring, moonlight through a slit window, dust drifting in beams.",
      "characters": ["Princess Aenor", "Maren Vale"]
    },
    {
      "scene_number": 14,
      "caption": "Brann picks the locks while Iskar holds the wards.",
      "visual_description": "Close on calloused fingers turning a thin pick in heavy shackles, behind them a glowing barrier shimmering across the cell door.",
      "characters": ["Brann Holt", "Iskar Tov", "Princess Aenor"]
    },
    {
      "scene_number": 15,
      "caption": "A dragon's roar shakes the cursed tower.",
      "visual_description": "Cracks racing up tower walls, loose stones tumbling, an enormous winged shadow blotting out a stained-glass window.",
      "characters": ["Maren Vale", "Princess Aenor", "Iskar Tov"]
    },
    {
      "scene_number": 16,
      "caption": "They flee down a collapsing spiral stair.",
      "visual_description": "Steps crumbling behind running figures, torchfire streaking past, the chamberlain wheezing as he clutches a bannister.",
      "characters": ["Maren Vale", "Princess Aenor", "Brann Holt", "Chamberlain Odo"]
    },
    {
      "scene_number": 17,
      "caption": "Captain Reeve makes a final stand to buy time.",
      "visual_description": "A lone armored figure planting her halberd in a doorway, sparks flaring behind her, fire-glow on her dented breastplate.",
      "characters": ["Captain Reeve", "Iskar Tov"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes across the trembling river bridge.",
      "visual_description": "A long stone bridge cracking under hurried feet at sunrise, the ruined city burning behind, river mist swirling below.",
      "characters": ["Maren Vale", "Princess Aenor", "Iskar Tov", "Brann Holt", "Chamberlain Odo"]
    }
  ]
}

